class Solution:
    def rangeTotals(self, sales: List[int], queries: List[List[int]]) -> List[int]:
        return [sum(sales[l:r + 1]) for l, r in queries]

code.java:
class Solution {
    public long[] rangeTotals(int[] sales, int[][] queries) {
        long[] out = new long[queries.length];
        for (int q = 0; q < queries.length; q++) {
            long total = 0;
            for (int k = queries[q][0]; k <= queries[q][1]; k++) total += sales[k];
            out[q] = total;
        }
        return out;
    }
}

