code.python:
class Solution:
    def rangeTotals(self, sales: List[int], queries: List[List[int]]) -> List[int]:
        prefix = [0]
        for s in sales:
            prefix.append(prefix[-1] + s)
        return [prefix[r + 1] - prefix[l] for l, r in queries]

