class Solution {
    public long[] rangeTotals(int[] sales, int[][] queries) {
        long[] prefix = new long[sales.length + 1];
        for (int i = 0; i < sales.length; i++) prefix[i + 1] = prefix[i] + sales[i];
        long[] out = new long[queries.length];
        for (int q = 0; q < queries.length; q++) out[q] = prefix[queries[q][1] + 1] - prefix[queries[q][0]];
        return out;
    }
}

