class Solution {
public:
    vector<long long> rangeTotals(vector<int>& sales, vector<vector<int>>& queries) {
        vector<long long> prefix(sales.size() + 1, 0);
        for (size_t i = 0; i < sales.size(); i++) prefix[i + 1] = prefix[i] + sales[i];
        vector<long long> out;
        for (auto& q : queries) out.push_back(prefix[q[1] + 1] - prefix[q[0]]);
        return out;
    }
};

