long long* rangeTotals(int* sales, int salesSize, int** queries, int queriesSize, int* queriesColSize, int* returnSize) {
    long long* prefix = malloc((salesSize + 1) * sizeof(long long));
    prefix[0] = 0;
    for (int i = 0; i < salesSize; i++) prefix[i + 1] = prefix[i] + sales[i];
    long long* out = malloc(queriesSize * sizeof(long long));
    for (int q = 0; q < queriesSize; q++) out[q] = prefix[queries[q][1] + 1] - prefix[queries[q][0]];
    free(prefix);
    *returnSize = queriesSize;
    return out;
}
